Create Table Proj_Team                             -- فريق العمل
( Id         BIGINT NOT NULL AUTO_INCREMENT,                           -- PK
  User_Id    BIGINT NOT NULL,                           -- المستخدم
  Status_Id  BIGINT Default 1 NOT NULL,                 -- الحالة
  Class1_Id  BIGINT Default 0 NOT NULL,                 -- تصنيف 1
  Class2_Id  BIGINT Default 0 NOT NULL,                 -- تصنيف 2
  Class3_Id  BIGINT Default 0 NOT NULL,                 -- تصنيف 3
